variables.expected_position:
{% set sd = trigger.event.data.service_data | default({}, true) %}
{% if trigger.event.data.service == 'set_cover_position' and sd.get('position') is not none %}
  {{ sd.get('position') | int }}
{% elif trigger.event.data.service == 'open_cover' %}
  100
{% elif trigger.event.data.service == 'close_cover' %}
  0
{% else %}
  {{ none }}
{% endif %}

variables.raw_entities:
{% set sd = trigger.event.data.service_data | default({}, true) %}
{% set raw = sd.get('entity_id', none) %}
{% if raw is string %}
  {{ [raw] }}
{% elif raw is iterable and raw is not mapping %}
  {{ raw | list }}
{% else %}
  {{ [] }}
{% endif %}

variables.group_targets:
{% set ns = namespace(out=[]) %}
{% for e in raw_entities %}
  {% set members = state_attr(e, 'entity_id') %}
  {% if (e | string).startswith('cover.') and members is iterable and members is not string and members is not mapping and (members | list | count > 0) %}
    {% set ns.out = ns.out + [e] %}
  {% endif %}
{% endfor %}
{{ ns.out | unique | list }}
